/* From Uiverse.io by Yaya12085 - Tags: card, cookies */
.__UIV_SCOPE__ .cookie-card {
  max-width: 320px;
  padding: 1rem;
  background-color: #fff;
  border-radius: 10px;
  box-shadow: 20px 20px 30px rgba(0, 0, 0, .05);
}

.__UIV_SCOPE__ .title {
  font-weight: 600;
  color: rgb(31 41 55);
}

.__UIV_SCOPE__ .description {
  margin-top: 1rem;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: rgb(75 85 99);
}

.__UIV_SCOPE__ .description a {
  --tw-text-opacity: 1;
  color: rgb(59 130 246);
}

.__UIV_SCOPE__ .description a:hover {
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
}

.__UIV_SCOPE__ .actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1rem;
  -moz-column-gap: 1rem;
  column-gap: 1rem;
  flex-shrink: 0;
}

.__UIV_SCOPE__ .pref {
  font-size: 0.75rem;
  line-height: 1rem;
  color: rgb(31 41 55 );
  -webkit-text-decoration-line: underline;
  text-decoration-line: underline;
  transition: all .3s cubic-bezier(0.4, 0, 0.2, 1);
  border: none;
  background-color: transparent;
}

.__UIV_SCOPE__ .pref:hover {
  color: rgb(156 163 175);
}

.__UIV_SCOPE__ .pref:focus {
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.__UIV_SCOPE__ .accept {
  font-size: 0.75rem;
  line-height: 1rem;
  background-color: rgb(17 24 39);
  font-weight: 500;
  border-radius: 0.5rem;
  color: #fff;
  padding-left: 1rem;
  padding-right: 1rem;
  padding-top: 0.625rem;
  padding-bottom: 0.625rem;
  border: none;
  transition: all .15s cubic-bezier(0.4, 0, 0.2, 1);
}

.__UIV_SCOPE__ .accept:hover {
  background-color: rgb(55 65 81);
}

.__UIV_SCOPE__ .accept:focus {
  outline: 2px solid transparent;
  outline-offset: 2px;
}
